        new() { Id = "wh-3", Name = "Warehouse C" },
    ];
}

namespace sv_0c267aab09204a03b8e25ad92feac7c6.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the latest low-stock alert count
/// and exposes an event so every subscribed component re-renders when new
/// data arrives — even components that did not trigger the poll.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Raised whenever <see cref="CurrentLowStockCount"/> changes.
    /// Subscribers MUST use <c>InvokeAsync(StateHasChanged)</c> because
    /// this event fires from a background timer thread, not from
    /// the Blazor synchronization context.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query that returns items below minimum stock
    /// levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by the polling component after fetching new data.
    /// Updates the cached count and notifies ALL subscribers.
    /// </summary>
    public void UpdateCount(int newCount)
    {
        CurrentLowStockCount = newCount;
        OnChange?.Invoke();
    }
}

