@page "/dashboard"
@using sv_0c267aab09204a03b8e25ad92feac7c6.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-3" style="max-width: 30rem;">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text">
            <strong>@Warehouse?.SelectedWarehouseName</strong>
            <span class="text-muted">(@Warehouse?.SelectedWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-3" style="max-width: 30rem;">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            <span class="badge bg-danger rounded-pill">@AlertService.CurrentLowStockCount</span>
        </h5>
        <p class="card-text text-muted">
            Polling every 10 seconds for items below minimum levels.
        </p>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseState? Warehouse { get; set; }

    private CancellationTokenSource? _cts;
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe to alert changes so this component re-renders
        // even if another component triggered the update.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override void OnParametersSet()
    {
        // Restart polling whenever the warehouse changes (cascading parameter update).
        StopPolling();
        StartPolling();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        var token = _cts.Token;
        _ = PollAsync(token);
    }

    private async Task PollAsync(CancellationToken token)
    {
        // Fire an initial fetch immediately so the badge isn't stale.
        await FetchAndBroadcast(token);

        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        try
        {
            while (await timer.WaitForNextTickAsync(token))
            {
                await FetchAndBroadcast(token);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when the component disposes or warehouse changes.
        }
    }

    private async Task FetchAndBroadcast(CancellationToken token)
    {
        if (Warehouse is null) return;

        var count = await AlertService.GetLowStockCountAsync(Warehouse.SelectedWarehouseId);

        if (!token.IsCancellationRequested)
        {
            // UpdateCount raises OnChange, which notifies ALL subscribers
            // (this component, the sidebar AlertBadge, etc.).
            AlertService.UpdateCount(count);
        }
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        StopPolling();
        AlertService.OnChange -= _handler;
    }
}

